--[[
    aw-shop.lua
    Sean Stoves (Solao) — 2026-08-05

    'list' in a shop, copied into a panel as rows you can click to buy from.
    The MUD's own list still scrolls past in the main window — this is an
    extra, and the extra is that the rows are buttons.

    What it reads:

        Num  Level  Price    Qty  Item
        ---  -----  -------  ---  -----------------------------------
          1      5       20  ---  [Potion] Optical Precision
          7     69      625    1  (Polished) plain tunic
        Quantity '---' means unlimited supply.

    Fixed width, and the Num column is the whole point: Aardwolf's 'buy' takes
    that number, so a row can be a button without guessing at keywords the way
    the hunt links have to. Qty is '---' for unlimited or a count for limited
    stock, and a sold-out line simply isn't listed.

    Mark rows with + and −, then buy the lot after a screen showing the bill.
    Nothing chains into wearing or wielding what you bought — same line the S&D
    panel draws: the client saves you typing, it doesn't play for you.

    Prices are not checked against your gold. The MUD already says no better
    than we could, and a client that greys out what it thinks you can't afford
    is wrong the moment you sell something.

    Ported from the Mudlet shopwin module. What changed for this client is
    noted where it happens: colour comes off the line through parseAnsiText
    into generated CSS classes because the sanitiser drops inline colour, the
    pager is gone because a div scrolls, and the quantity presets became
    steppers because a form can't tell you which of its buttons was pressed.
]]

plugin = {
    id          = "aw-shop",
    name        = "Aardwolf Shop",
    version     = "1.5.2",
    author      = "Solao",
    description = "Shop stock in a panel. Click a name to appraise it, a number to buy that many.",
    settings    = { saveState = true },
}

-- @category widgets

local TAG  = "$Y[Shop v" .. plugin.version .. "]$w "

local VAR = "aw_shop_cfg"

--[[
    Aardwolf's buy takes a count: 'buy 20 2' is twenty of item 2, which is why
    each row carries its own marker rather than the client remembering a
    quantity for you. A remembered quantity is the kind of state that empties
    your gold when you forget it's set; a row that starts at zero every list
    can't.

    The ceiling is per line, and limited stock lowers it to whatever is on the
    shelf. 1000 of a 9,300 gold item is nine million — a fat-fingered extra
    zero shouldn't be reachable.
]]
local QVALMAX = 1000

--[[
    Font, ours rather than the client's.

    The widget cog has Font Family, Size and Weight, but they set the WIDGET's
    font and this panel's stylesheet names its own — so those controls could
    never reach the rows. Rather than depend on inheriting through a sanitised
    iframe, the sizes are generated: everything scales off one base, and the
    stack is one of three.

    10 to match S&D's rows — 'No quest targets' is 10px there, and two panels
    open side by side should read at one size rather than nearly one.

    The slots are still keyed to 11, which is what the panel was drawn at, so
    the base carries an offset rather than the numbers being renamed. Below 8
    the level column stops lining up; above 18 a shop stops fitting a sensible
    window.
]]
local FS_MIN, FS_MAX = 8, 18

local FONTS = {
    mono   = '"JetBrains Mono", ui-monospace, SFMono-Regular, Menlo, monospace',
    system = 'system-ui, -apple-system, "Segoe UI", sans-serif',
    serif  = 'Georgia, "Times New Roman", serif',
}

local FONT_ORDER = { "mono", "system", "serif" }

local cfg = {
    on   = true,
    fs   = 10,
    ff   = "mono",
    gag  = false,    -- a copy by default; the MUD's own list still prints
    hide = true,     -- put the panel away when you leave the shop
}

local widget  = nil
local view    = "list"       -- "list" | "settings"
local items   = {}
local listing = false        -- between the header and the footer
local armed   = nil          -- the timer that disarms a list with no footer
local vnum    = 0            -- the room the current list came from
local pending = nil          -- what the confirm screen is about to spend
local want    = {}           -- how many of each row, by row index

local function trim(s)
    return (string.gsub(tostring(s or ""), "^%s*(.-)%s*$", "%1"))
end

--[[
    Walked backwards rather than the usual gsub-until-no-more loop.

    That loop terminates on gsub's SECOND return, the replacement count — and
    this runtime is not a Lua VM. Written the idiomatic way, commas(0) spun
    forever the moment init() called render(), which locked the client on
    install before a single line of MUD output existed. Who's version does the
    same walk for the same reason.
]]
local function commas(n)
    n = tonumber(n)
    if type(n) ~= "number" then return "0" end

    local s, out, c = tostring(math.floor(n)), "", 0
    for i = string.len(s), 1, -1 do
        out = string.sub(s, i, i) .. out
        c = c + 1
        if c % 3 == 0 and i > 1 then out = "," .. out end
    end
    return out
end

--[[
    Read capture n.

    The guide says captures[1] is the first group. Our own S&D hedges by also
    checking captures[0], because arrays crossing the Lua/JS boundary arrive
    0-indexed and nobody wrote down which side of that line this one lands on.
    The wildcards table sidesteps it entirely — it is keyed by the STRING "1",
    so there is no index base to get wrong. Try that first, then both bases.

    Getting this wrong costs a shop row parsed one column out, which reads as a
    price where a level should be and would happily buy the wrong thing.
]]
local function cap(c, w, n)
    if type(w) == "table" and type(w[tostring(n)]) == "string" then
        return w[tostring(n)]
    end
    if type(c) == "table" then
        if type(c[n]) == "string" then return c[n] end
        if type(c[n - 1]) == "string" then return c[n - 1] end
    end
    return ""
end

--[[
    What the marked rows come to.

    Cheap enough to recompute on every press — a shop list is tens of rows, not
    thousands — and recomputing beats keeping a running figure in step with a
    table that four different actions can change.
]]
local function total_of()
    local t = 0
    for i, e in ipairs(items) do
        t = t + e.price * (want[i] or 0)
    end
    return t
end

--[[
    The most of one line you're allowed to mark.

    Aardwolf prints '---' for unlimited and a count for limited stock, and it
    simply won't sell you more than it has — so a marker that can run past the
    count is only ever a way to build a bill that can't be paid out. Limited
    stock caps at what's on the shelf; everything else caps at QVALMAX.
]]
local function stock_of(e)
    if type(e) ~= "table" then return 0 end

    local n = tonumber(e.qty)
    if n and n > 0 and n < QVALMAX then return n end

    return QVALMAX
end

--[[
    How much one press moves a count. Shift for ten, and nothing else.

    Ctrl was five until it turned out to raise the context menu on a Mac, which
    is the platform this is being written on — a modifier the OS has already
    claimed is not available to claim again.

    Whether the client forwards modifiers on a widget action is not documented
    — the guide lists x, y and button for a click and says nothing about the
    action pair, which is ours anyway. So both spellings are tried and the
    fallback is one. If modifiers never arrive, every press is a single step:
    slower than intended, never a bigger purchase than intended.
]]
local function step_of(d)
    if type(d) ~= "table" then return 1 end
    if d.shiftKey == true or d.shift == true then return 10 end
    return 1
end

local function esc(s)
    s = tostring(s or "")
    s = string.gsub(s, "&", "&amp;")
    s = string.gsub(s, "<", "&lt;")
    s = string.gsub(s, ">", "&gt;")
    s = string.gsub(s, '"', "&quot;")
    return s
end

---
-- persistence
---

--[[
    saveTable is wiped when a plugin is removed and re-added, so the same blob
    goes into a world variable as well — those survive. Whichever is there on
    load wins, table first.
]]
local function save_cfg()
    saveTable("aw_shop", cfg)
    pcall(function()
        setVariable(VAR, '{"on":' .. (cfg.on and "true" or "false")
            .. ',"gag":' .. (cfg.gag and "true" or "false")
            .. ',"hide":' .. (cfg.hide and "true" or "false")
            .. ',"fs":' .. tostring(cfg.fs)
            .. ',"ff":"' .. cfg.ff .. '"}')
    end)
end

---
-- capture
---

--[[
    Aardwolf paints item names, and the colour carries meaning — the bonus-loot
    bracket tier, and shop items that are quest or clan gear. Read it off the
    line rather than deciding for ourselves what an item should look like.

    parseAnsiText gives back segments with a hex colour each; the item name is
    the tail of the line, so the last coloured segment is the one that describes
    it. Anything that isn't a #rrggbb is dropped rather than trusted — this
    string ends up in a generated CSS rule.
]]
local function colour_of(raw)
    if type(raw) ~= "string" or raw == "" then return nil end

    local ok, segs = pcall(parseAnsiText, raw)
    if not ok or type(segs) ~= "table" then return nil end

    local hex = nil
    for _, seg in pairs(segs) do
        if type(seg) == "table" and type(seg.color) == "string" then
            local c = string.match(seg.color, "^#%x%x%x%x%x%x$")
            if c and string.lower(c) ~= "#000000" then hex = c end
        end
    end

    return hex
end

--[[
    Which room we're standing in, or 0 when the MUD hasn't said.

    Only used to notice you've walked out of the shop. A 0 never matches a real
    vnum, so an unknown room simply leaves the panel up rather than closing it
    on a guess.
]]
local function room_now()
    for _, name in ipairs({ "room.info", "Room.Info" }) do
        local d = getGMCPData(name)
        if type(d) == "table" and tonumber(d.num) then return tonumber(d.num) end
    end
    return 0
end

local function stop_listing()
    listing = false
    if armed then
        pcall(removeTimer, armed)
        armed = nil
    end
end

--[[
    Forward declarations. The trigger callbacks below call both of these, and
    both are defined further down — without these lines the calls resolve to
    globals of the same name, which are nil, and fail silently. That has cost
    this codebase about five separate bugs.
]]
local render
local raise
local build_widget

local function on_head()
    if not cfg.on then return end

    items   = {}
    want    = {}
    stop_listing()
    listing = true
    vnum    = room_now()

    -- a list with no footer would otherwise leave this armed for the session
    armed = addTimer(10000, function()
        stop_listing()
        render()
    end)

    raise()
    render()

    if cfg.gag then return false end
end

local function on_row(c, line, w, raw)
    if not (cfg.on and listing) then return end

    local item = trim(cap(c, w, 5))
    if item == "" then return end

    table.insert(items, {
        num   = tonumber(cap(c, w, 1)) or 0,
        lvl   = tonumber(cap(c, w, 2)) or 0,
        price = tonumber((string.gsub(cap(c, w, 3), ",", ""))) or 0,
        qty   = trim(cap(c, w, 4)),
        item  = item,
        col   = colour_of(raw),
        raw   = (type(raw) == "string") and raw or nil,
    })

    if cfg.gag then return false end
end

local function on_foot()
    if not (cfg.on and listing) then return end

    stop_listing()
    render()

    --[[
        Publish the parsed list.

        The Loot Tracker wants shop stock too, and it had its own trigger on
        the same rows — two parses of one line, free to drift apart and certain
        to eventually. This panel already reads level, price, quantity and
        colour properly, so it says what it found and anything interested
        listens.

        Sent over the broadcast channel, not the emit/on pair the guide
        documents: this build has no 'on', and a global the runtime doesn't
        have throws on the way in rather than reading as nil — so there is no
        way to try it and fall back. Core and S&D already use this channel.

        Sent as a JSON STRING rather than a table. Core only ever puts strings
        on this channel, so whether a table survives the crossing is untested —
        and a table that arrives mangled fails silently, which is the worst way
        for a hand-off to fail. Encoding costs nothing at this size and leaves
        nothing to find out.

        Nobody listening costs one message nobody reads.
    ]]
    local ok, blob = pcall(json.encode, { roomid = vnum, items = items })
    if ok and type(blob) == "string" then
        pcall(broadcastPlugin, "aw-shop-list", blob)
    end

    if cfg.gag then return false end
end

---
-- paint
---

