--[[
    The sanitiser drops colour out of an inline style attribute but keeps the
    one <style> element, so the item colours are emitted as rules — one class
    per distinct colour in this list, built fresh each paint. That is the only
    reliable way to vary colour in a widget, and it's why the stylesheet is
    assembled here instead of being a constant.
]]
--[[
    Fill in the stylesheet's two font slots.

    There used to be nineteen — one per rule, each with its own pixel value
    worked out from the base. They substituted correctly (checked by hand, in
    Lua) and still only the item names changed size on screen, which means
    nineteen separate declarations were nineteen chances for something between
    here and the glass to disagree with us.

    So the panel carries ONE size and every rule is a fraction of it. Either
    the whole panel scales or none of it does, and 'none of it' is a far
    easier thing to chase than 'some of it'.

    The fractions are the old pixel values over 11, which is what the panel was
    drawn at, so nothing shifts at the default.
]]
local function sized(css)
    css = string.gsub(css, "{{ff}}", FONTS[cfg.ff] or FONTS.mono)
    css = string.gsub(css, "{{base}}", cfg.fs .. "px")
    return css
end

--[[
    Drop every mark and put the panel back to zero.

    The counts and the total are written with setBoundValue, and a bound value
    outlives the content it was written into — repainting alone left the old
    numbers on screen, which is why 'clear' looked like it did nothing. So the
    zeros are pushed explicitly, AFTER the repaint, or the repaint would just
    overwrite them back.
]]
--[[
    Re-apply the stylesheet by rebuilding the widget.

    Changing the font size rewrote the <style> element and nothing moved. The
    CSS is right — substitute it by hand and the rules come out with the new
    sizes — so the stylesheet appears to be taken once per widget and ignored
    on later content. That matches the other stateful thing this layer does:
    a setBoundValue survives the content it was written into.

    A rebuild is the one way we know puts a new stylesheet in place, and it is
    already how raise() recovers a stranded panel. Only font changes pay for
    it, which is a handful of presses in a settings pane, not anything on the
    hot path.
]]
local function restyle()
    if not widget then return end

    pcall(destroyWidget, widget)
    build_widget()
    showWidget(widget)
    render()

    pcall(setWidgetAppearance, widget, { zIndex = 9999 })
end

local function clear_marks()
    want = {}
    render()

    for i = 1, #items do
        pcall(setBoundValue, widget, "q" .. i, "0")
    end
    pcall(setBoundValue, widget, "total", "0")
end

--[[
    An item name drawn the way the MUD painted it, run by run.

    colour_of picks ONE colour for a name and everything downstream used it, so
    'Red Kite feather earring' came out flat while the MUD has 'feather' in a
    different colour to the rest. One hex per item cannot represent a name the
    MUD colours in pieces.

    The name sits at the end of the row behind the number, level, price and
    quantity columns, which this panel lays out itself — so only the characters
    from the name's offset to the end of the name get emitted.

    Falls back to the single colour when there is no raw line — rows restored
    from a previous session have none — or when anything below doesn't line up.
]]
local function name_runs(e, cls)
    if type(e.raw) ~= "string" then return nil end

    local ok, segs = pcall(parseAnsiText, e.raw)
    if not ok or type(segs) ~= "table" then return nil end

    local plain = ""
    for _, seg in pairs(segs) do
        if type(seg) == "table" and type(seg.text) == "string" then
            plain = plain .. seg.text
        end
    end

    --[[
        Hand-rolled rather than string.find(plain, item, 1, true), which came
        back 1 for a name two dozen characters in and put the whole row —
        number, level, price, dashes and all — in the name column. Same shape
        of hole as the init argument in note 11.
    ]]
    local at, need, hay = nil, string.len(e.item), string.len(plain)
    if need == 0 or need > hay then return nil end

    for i = 1, hay - need + 1 do
        if string.sub(plain, i, i + need - 1) == e.item then
            at = i
            break
        end
    end
    if not at then return nil end

    local from, to = at, at + need - 1
    local out, pos, got = "", 1, ""

    for _, seg in pairs(segs) do
        if type(seg) == "table" and type(seg.text) == "string" and seg.text ~= "" then
            local a, b = pos, pos + string.len(seg.text) - 1
            pos = b + 1

            -- the slice of this run that overlaps the name, if any
            if b >= from and a <= to then
                local lo = (a > from) and a or from
                local hi = (b < to) and b or to
                local part = string.sub(seg.text, lo - a + 1, hi - a + 1)
                got = got .. part

                local hex = (type(seg.color) == "string")
                    and string.match(seg.color, "^#%x%x%x%x%x%x$") or nil
                local k = hex and cls[hex] or nil

                if k then
                    out = out .. '<span class="' .. k .. '">' .. esc(part) .. "</span>"
                else
                    out = out .. esc(part)
                end
            end
        end
    end

    -- if what came out isn't the name, don't show it
    if got ~= e.item then return nil end
    return out
end

local function css_for(list)
    local seen, out, n = {}, {}, 0

    local function take(hex)
        if type(hex) ~= "string" then return end
        if not string.match(hex, "^#%x%x%x%x%x%x$") then return end
        if hex == "#000000" then return end        -- "no colour", not black
        if seen[hex] then return end

        n = n + 1
        seen[hex] = "c" .. n
        table.insert(out, "    .arc-w ." .. seen[hex] .. " { color: " .. hex .. "; }")
    end

    for _, e in ipairs(list) do
        take(e.col)

        -- every colour the row actually uses, so a name painted in pieces has
        -- a class for each piece
        if type(e.raw) == "string" then
            local ok, segs = pcall(parseAnsiText, e.raw)
            if ok and type(segs) == "table" then
                for _, seg in pairs(segs) do
                    if type(seg) == "table" then take(seg.color) end
                end
            end
        end
    end

    return sized(CSS_HEAD) .. table.concat(out, "\n") .. "\n</style>\n", seen
end

render = function()
    if not widget then return end

    local bar = '<span class="stat"><b>' .. commas(#items) .. '</b> for sale</span>'
        .. '<span class="sp"></span>'
        --[[
            Hide first, gear hard right — the order every other panel uses. A
            control that moves position between panels is one people stop
            trusting.

            Hide stays a word rather than becoming a second glyph beside the
            cog: with the title bar off it is the only way to put the panel
            away, and unlike the client's own × it doesn't strand the widget.
        ]]
        .. '<div class="tb" data-mud-action="close" title="put the panel away; '
        .. 'it comes back on the next list">hide</div>'
        .. '<div class="tb' .. (view ~= "list" and " on" or "")
        .. '" data-mud-action="view" title="settings">'
        .. (view ~= "list" and "&#9664; back" or "&#9881;") .. '</div>'

    local css, cls = css_for(items)
    local body, foot = "", ""

    if view == "settings" then
        body = '<div class="sec">Capture</div>'
            .. '<div class="bar" style="padding:0;border:0">'
            .. '<div class="tb' .. (cfg.on and " on" or "") .. '" data-mud-action="on">'
            .. (cfg.on and "on" or "off") .. '</div>'
            .. '<div class="tb' .. (cfg.gag and " on" or "") .. '" data-mud-action="gag">'
            .. 'hide output</div>'
            .. '<div class="tb' .. (cfg.hide and " on" or "") .. '" data-mud-action="autohide">'
            .. 'close on leave</div>'
            .. '</div>'
            .. '<div class="note">Type <code>list</code> in a shop. <b>Hide output</b> keeps '
            .. 'the MUD\'s own list out of the terminal so only this panel shows it. '
            .. '<b>Close on leave</b> puts the panel away when you walk out &mdash; turn it '
            .. 'off to keep a list up while you go and fetch the gold for it.</div>'
            .. '<div class="sec">Text</div>'
            .. '<div class="bar" style="padding:0;border:0">'
            .. '<div class="tb" data-mud-action="smaller">&minus;</div>'
            .. '<div class="tb">' .. cfg.fs .. 'px</div>'
            .. '<div class="tb" data-mud-action="bigger">+</div>'
            .. '<div class="tb" data-mud-action="font">' .. cfg.ff .. '</div>'
            .. '</div>'
            .. '<div class="note">The widget cog has its own font settings, but those apply '
            .. 'to the widget and this panel names its own &mdash; so these are the ones that '
            .. 'reach the rows. Sizes run ' .. FS_MIN .. ' to ' .. FS_MAX
            .. '; the columns stop lining up below that and a shop stops fitting above it.</div>'
            .. '<div class="sec">Buying</div>'
            .. '<div class="note">Mark what you want with <b>+</b> and <b>&minus;</b> &mdash; '
            .. 'hold <b>shift</b> for ten at a time. The footer totals '
            .. 'it as you go, and <b>buy marked</b> shows you the whole bill before any gold '
            .. 'moves. Nothing over ' .. commas(QVALMAX) .. ' of one item.</div>'

    elseif view == "confirm" then
        --[[
            The total lives here rather than under the buy button because a
            figure that updates as you type needs JavaScript, and widget HTML
            is sanitised — no script, no onclick, no listeners. A review step
            is the honest version of the same safety: you see exactly what is
            about to be spent, on one screen, before anything is sent.
        ]]
        body = '<div class="sec">About to buy</div>'

        for _, r in ipairs(pending.rows) do
            local runs = name_runs(r, cls)

            body = body .. '<div class="it">'
                .. '<span class="lv">' .. r.qty .. '&times;</span>'
                .. '<span class="nm' .. (runs and "" or (cls[r.col] and (" " .. cls[r.col]) or "")) .. '">'
                .. (runs or esc(r.item)) .. '</span>'
                .. '<span class="pr">' .. commas(r.cost) .. '</span>'
                .. '</div>'
        end

        body = body .. '<div class="tot"><span>total</span><b>'
            .. commas(pending.total) .. ' gold</b></div>'

        foot = '<div class="bar" style="justify-content:flex-end">'
            .. '<div class="tb" data-mud-action="cancel">cancel</div>'
            .. '<div class="tb on" data-mud-action="confirm">buy it</div></div>'

    else
        if #items == 0 then
            body = '<div class="empty">Nothing listed &mdash; type <code>list</code> in a shop</div>'
        else
            --[[
                No form, and that is the point.

                The number fields were submit-driven, and every submit button's
                value came back on every submit — pressing "buy marked" arrived
                carrying a row button's value, so there was no way to tell which
                control had actually been pressed. Buttons that each own one
                action can't be confused for one another.

                It also buys a real running total: the quantities live in Lua
                now, so the footer figure is always the true one rather than
                something a form has to hand over first.
            ]]
            for i, e in ipairs(items) do
                local n = want[i] or 0

                local runs = name_runs(e, cls)

                body = body .. '<div class="it">'
                    .. '<span class="lv">' .. e.lvl .. '</span>'
                    .. '<span class="nm' .. (runs and "" or (cls[e.col] and (" " .. cls[e.col]) or ""))
                    .. '" data-mud-action="appraise" data-mud-data="' .. i
                    .. '" title="appraise ' .. esc(e.item) .. ' &mdash; costs nothing">'
                    .. (runs or esc(e.item)) .. '</span>'
                    .. '<span class="pr">' .. commas(e.price) .. '</span>'
                    .. (e.qty ~= "---" and ('<span class="st">x' .. esc(e.qty) .. '</span>') or "")
                    .. '<div class="stp" data-mud-action="dec" data-mud-data="' .. i
                    .. '" title="hold SHIFT to move by 10">&minus;</div>'
                    --[[
                        Bound, not redrawn. A repaint of a 48 row list on every
                        press would throw away the scroll position, so the count
                        and the total are written into marked elements instead
                        and the markup around them stays put.
                    ]]
                    .. '<span class="qv" data-mud-bind="q' .. i .. '">' .. n .. '</span>'
                    .. '<div class="stp" data-mud-action="inc" data-mud-data="' .. i
                    .. '" title="hold SHIFT to move by 10">+</div>'
                    .. '</div>'
            end

            foot = '<div class="foot">'
                .. '<span class="tl">total</span>'
                .. '<b data-mud-bind="total">' .. commas(total_of()) .. '</b>'
                .. '<span class="sp"></span>'
                .. '<div class="tb" data-mud-action="clearq">clear</div>'
                .. '<div class="tb on" data-mud-action="buyall">buy marked</div>'
                .. '</div>'
        end
    end

    setWidgetProperty(widget, "content", css
        .. '<div class="arc-w"><div class="bar">' .. bar .. '</div>'
        .. '<div class="body">' .. body .. '</div>' .. foot .. '</div>')
end

---
-- buying
---

-- the row index, not the shop's number
local function buy(i, qty)
    local e = items[tonumber(i) or 0]
    if not e then return end

    qty = math.floor(tonumber(qty) or 1)

    --[[
        Belt and braces on the way out: the steppers already clamp to the
        shelf, but '/shop buy' takes a number off the command line and this is
        the last place before it becomes a purchase.
    ]]
    if qty < 1 then qty = 1 end

    local top = stock_of(e)
    if qty > top then
        utilprint(TAG .. "$Ronly " .. commas(top)
            .. ((top < QVALMAX) and " of that in stock" or " at a time")
            .. " - not sending it.$w")
        return
    end

    -- 'buy 1 3' and 'buy 3' are the same thing; send the shorter one
    if qty > 1 then
        send("buy " .. qty .. " " .. e.num)
    else
        send("buy " .. e.num)
    end
end

--[[
    Appraise is the only way to see what a shop item actually does, and it
    costs nothing — which is why it's on the name. The click you'll make by
    accident, on the item you were reading, is the one that spends no gold.
]]
local function appraise(i)
    local e = items[tonumber(i) or 0]
    if not e then return end
    send("appraise " .. e.num)
end

---
-- setup
---

--[[
    Widget setup lives in a function because the panel sometimes has to be
    rebuilt — see raise(). destroyWidget frees the event handlers registered
    against it, so they are re-registered here rather than leaking one set per
    rebuild.
]]
--[[
    Put the panel up and keep it on top.

    showWidget alone was not enough. Closing the panel from the client's own
    titlebar leaves it in a state showWidget doesn't lift — the widget stays
    down until you go into the plugin list and unhide it by hand, which is a
    long way to walk for a popup that is supposed to reappear on its own.

    So: ask, then check. widgetInfo 7 reports visibility, and if the widget is
    still down after being told to show, it gets destroyed and rebuilt.
    destroyWidget also frees the handlers registered against it, which is why
    build_widget re-registers them rather than init doing it once.

    Only an explicit false triggers the rebuild. widgetInfo returning nil means
    the client didn't answer, and rebuilding the panel on every list because a
    query came back empty would be worse than the bug.

    Z-order is reasserted on the way up. 49 is the client's ceiling — it caps
    widgets there so they can never cover dialogs or menus.
]]
raise = function()
    showWidget(widget)

    local ok, vis = pcall(widgetInfo, widget, 7)
    if ok and vis == false then
        pcall(destroyWidget, widget)
        build_widget()
        showWidget(widget)

        --[[
            A rebuilt widget doesn't take content in the same breath — the
            first list after closing the panel from the titlebar came back
            empty and it took a SECOND list to fill it. Paint again once the
            new widget has settled.

            140ms is a beat, not a measurement. It is late enough to land after
            the widget exists and early enough that nobody waits for it; the
            immediate render still happens too, so this is a second attempt
            rather than the only one.
        ]]
        addTimer(140, function()
            render()
            pcall(setWidgetZOrder, widget, 49)
        end)
    end

    --[[
        Two different ceilings for the same idea: createWidget and
        setWidgetZOrder both cap at 49, while setWidgetAppearance clamps zIndex
        to 9999. A shop list is a popup you called up deliberately and is meant
        to sit over whatever it lands on, so it takes the higher one — and
        falls back to the capped call if that field isn't honoured.
    ]]
    pcall(setWidgetAppearance, widget, { zIndex = 9999 })
    pcall(setWidgetZOrder, widget, 49)
end

build_widget = function()
    widget = createWidget({
        type     = "html",
        name     = "shop",
        title    = "Shop",
        position = { x = 560, y = 140 },
        size     = { width = 520, height = 420 },
        visible  = false,
        -- 49 is createWidget's ceiling; raise() lifts it to 9999 through
        -- setWidgetAppearance, which clamps far higher. A shop list is
        -- ephemeral — summoned, then dismissed — so it belongs on top.
        zIndex   = 49,
        --[[
            No title bar. Every panel here draws its own header with its own
            controls, so the client's chrome was a second title above ours
            saying the same thing.

            This is a plugin DEFAULT, not a lock — it's declared through the
            appearance table at creation, which the user can still override in
            the widget's own cog. autoHideSettingsCog keeps that cog reachable
            on hover rather than it going away with the bar.
        ]]
        appearance = {
            showTitleBar        = false,
            autoHideSettingsCog = true,
            --[[
                Ephemeral windows sit on top. This one is summoned by a 'list'
                and dismissed when you leave, so it is never what another panel
                needs to be in front of — and a popup that opens underneath
                something is a popup that didn't open.

                9999 because setWidgetAppearance clamps there, while the
                zIndex above and setWidgetZOrder both cap at 49.
            ]]
            zIndex              = 9999,
        },
    })

    registerWidgetEvent(widget, "action", function(data)
        if type(data) ~= "table" then return end

        local act = tostring(data.action or "")
        local arg = tostring(data.data or "")

        if act == "inc" or act == "dec" then
            local i = tonumber(arg)
            if not i or not items[i] then return end

            local top = stock_of(items[i])
            local n = (want[i] or 0) + ((act == "inc") and step_of(data) or -step_of(data))
            if n < 0 then n = 0 end
            if n > top then n = top end
            want[i] = (n > 0) and n or nil

            --[[
                Written into the two bound elements rather than repainting.
                Rebuilding a 48 row list to change one number would reset the
                scroll every press, which makes the bottom of a long shop list
                unusable.
            ]]
            pcall(setBoundValue, widget, "q" .. i, tostring(n))
            pcall(setBoundValue, widget, "total", commas(total_of()))
            return

        elseif act == "clearq" then
            clear_marks()
            return

        elseif act == "buyall" then
            local rows, total = {}, 0

            for i, e in ipairs(items) do
                local n = want[i] or 0
                if n > 0 then
                    local cost = e.price * n
                    total = total + cost
                    table.insert(rows, { i = i, qty = n, cost = cost,
                                         item = e.item, col = e.col, num = e.num,
                                         raw = e.raw })
                end
            end

            if #rows == 0 then
                utilprint(TAG .. "mark something first - press + beside what you want.")
                return
            end

            pending = { rows = rows, total = total }
            view    = "confirm"
            render()
            return

        elseif act == "appraise" then
            appraise(tonumber(arg))
            return

        elseif act == "close" then
            hideWidget(widget)
            return

        elseif act == "confirm" then
            --[[
                The one place gold actually leaves in bulk. Sent per line
                rather than as one command because Aardwolf's buy takes one
                item number; the confirm screen is what made this a single
                decision rather than a dozen.
            ]]
            if type(pending) == "table" then
                for _, r in ipairs(pending.rows) do
                    buy(r.i, r.qty)
                end
                utilprint(TAG .. "bought " .. #pending.rows .. " line(s) for "
                    .. commas(pending.total) .. " gold.")
            end

            pending = nil
            view    = "list"
            clear_marks()
            return

        elseif act == "cancel" then
            pending = nil
            view    = "list"

        elseif act == "view" then
            -- anything that isn't the list goes back to it, confirm included
            pending = nil
            view = (view ~= "list") and "list" or "settings"

        elseif act == "on" then
            cfg.on = not cfg.on
            save_cfg()

        elseif act == "gag" then
            cfg.gag = not cfg.gag
            save_cfg()

        elseif act == "autohide" then
            cfg.hide = not cfg.hide
            save_cfg()

        elseif act == "bigger" or act == "smaller" then
            cfg.fs = cfg.fs + ((act == "bigger") and 1 or -1)
            if cfg.fs < FS_MIN then cfg.fs = FS_MIN end
            if cfg.fs > FS_MAX then cfg.fs = FS_MAX end
            save_cfg()
            restyle()
            return

        elseif act == "font" then
            -- cycles rather than a dropdown: three stacks, and a <select> in a
            -- sanitised widget can only report through a form we no longer have
            local at = 1
            for i, name in ipairs(FONT_ORDER) do
                if name == cfg.ff then at = i end
            end
            cfg.ff = FONT_ORDER[(at % #FONT_ORDER) + 1]
            save_cfg()
            restyle()
            return
        end

        render()
    end)
end

function init()
    build_widget()

    local saved = loadTable("aw_shop")

    if type(saved) ~= "table" then
        local ok, raw = pcall(function() return getVariable(VAR) end)
        if ok and type(raw) == "string" and raw ~= "" then
            local dok, data = pcall(json.decode, raw)
            if dok and type(data) == "table" then saved = data end
        end
    end

    if type(saved) == "table" then
        if saved.on == false then cfg.on = false end
        if saved.gag == true then cfg.gag = true end
        if saved.hide == false then cfg.hide = false end

        local fs = tonumber(saved.fs)
        if fs and fs >= FS_MIN and fs <= FS_MAX then cfg.fs = math.floor(fs) end
        if type(saved.ff) == "string" and FONTS[saved.ff] then cfg.ff = saved.ff end
    end

    save_cfg()

    --[[
        Triggers rather than onLine, because a trigger callback returning false
        gags the line and still runs — which is the whole job here. Comms does
        its gagging in onLine for the opposite reason: a line dropped there
        fires no triggers at all, so its captures had to live in the same pass.
        Nothing else needs to see shop rows, so this side of that trade is free.

        Regex is JavaScript flavour, and opting in is required — the default
        matcher is substring, which would match none of this.
    ]]
    addTrigger("^Num\\s+Level\\s+Price\\s+Qty\\s+Item\\s*$", on_head, { type = "regex" })

    addTrigger("^\\s*(\\d+)\\s+(\\d+)\\s+([\\d,]+)\\s+(---|\\d+)\\s+(\\S.*?)\\s*$",
        on_row, { type = "regex" })

    addTrigger("^(?:Quantity '---' means unlimited supply\\.|To see the stats of an item in the store, use 'Appraise <Item>'\\.)$",
        on_foot, { type = "regex" })

    render()

    registerCommand("shop", function(args)
        local a = args
        if type(a) == "table" then a = table.concat(a, " ") end
        a = trim(a)

        local verb, rest = string.match(a, "^(%S*)%s*(.*)$")
        verb = string.lower(verb or "")
        rest = trim(rest)

        if verb == "" or verb == "show" then
            raise()

        elseif verb == "hide" then
            hideWidget(widget)

        elseif verb == "on" or verb == "off" then
            cfg.on = (verb == "on")
            save_cfg()
            render()
            utilprint(TAG .. (cfg.on and "'list' is copied to the panel."
                or "main window only."))

        elseif verb == "gag" then
            cfg.gag = not cfg.gag
            save_cfg()
            render()
            utilprint(TAG .. (cfg.gag and "panel only — the list is hidden from the main window."
                or "the list prints in both places."))

        elseif verb == "autohide" or verb == "keep" then
            cfg.hide = (verb == "autohide")
            save_cfg()
            render()
            utilprint(TAG .. (cfg.hide and "the panel closes when you leave the shop."
                or "the panel stays up until you close it."))

        elseif verb == "font" then
            local n = tonumber(rest)

            if n then
                if n < FS_MIN then n = FS_MIN end
                if n > FS_MAX then n = FS_MAX end
                cfg.fs = math.floor(n)
            elseif rest ~= "" and FONTS[string.lower(rest)] then
                cfg.ff = string.lower(rest)
            elseif rest ~= "" then
                utilprint(TAG .. "$Rfont is a size " .. FS_MIN .. "-" .. FS_MAX
                    .. " or one of: " .. table.concat(FONT_ORDER, ", ") .. "$w")
                return
            end

            save_cfg()
            restyle()
            utilprint(TAG .. "text is " .. cfg.fs .. "px " .. cfg.ff .. ".")

        elseif verb == "buy" then
            local n, q = string.match(rest, "^(%d+)%s*(%d*)$")
            if not n then
                utilprint(TAG .. "$Rusage: /shop buy <row> [how many]$w")
            else
                buy(tonumber(n), tonumber(q))
            end

        elseif verb == "appraise" or verb == "app" then
            local n = tonumber(rest)
            if not n then
                utilprint(TAG .. "$Rusage: /shop appraise <row>$w")
            else
                appraise(n)
            end

        elseif verb == "clear" then
            items = {}
            clear_marks()
            utilprint(TAG .. "cleared.")

        else
            utilprint(TAG .. "shop stock in a panel.")
            utilprint("$w  /shop                          show the panel")
            utilprint("$w  /shop hide                     put it away")
            utilprint("$w  /shop on | off                 copy 'list' to the panel, or don't")
            utilprint("$w  /shop gag                      hide the list from the main window")
            utilprint("$w  /shop autohide | keep          close the panel when you leave, or don't")
            utilprint("$w  /shop buy <row> [n]            buy that row outright, no marking")
            utilprint("$w  /shop appraise <row>           same as clicking the name; costs nothing")
            utilprint("$w  /shop font <size|name>         text size 8-18, or mono | system | serif")
            utilprint("$w  /shop clear                    empty it")
            utilprint(TAG .. "state: " .. (cfg.on and "on" or "off")
                .. ", " .. (cfg.gag and "panel only" or "printed in both")
                .. ", " .. (cfg.hide and "closes on leave" or "stays up")
                .. ", " .. cfg.fs .. "px " .. cfg.ff
                .. ", " .. #items .. " item(s) listed.")
        end
    end, "shop stock in a panel; click a row to buy from it")

    --[[
        Core owns Core.Supports.Set and builds the union from these
        declarations. Sending our own would REPLACE Aardwolf's record of every
        other plugin's subscriptions, including the room package the built-in
        mapper runs on.

        Room is wanted for one thing: noticing you've left.
    ]]
    broadcastPlugin("aw-gmcp", "Room")

    --[[
        The panel is a popup. It appears when a list arrives and goes away when
        you walk out of the shop, because at that point it describes stock you
        can no longer buy — and a stale shop list you CAN still click is worse
        than no panel at all.

        Tied to the room changing rather than to a timer: how long you spend
        reading a shop list is not something a countdown can know.
    ]]
    local function left_shop()
        if not cfg.hide then return end

        local now = room_now()
        if now == 0 or vnum == 0 or now == vnum then return end

        vnum = 0
        items = {}
        stop_listing()
        hideWidget(widget)
        render()
    end

    onGMCPUpdate("room.info", left_shop)
    onGMCPUpdate("Room.Info", left_shop)
end
